jira.setSummary("jira:SYN-45","Rebooking: keep the original fare on long crossings when moving to a dearer sailing");
const f:Finding[]=[
{kind:"conflict",lines:[1],says:"The current story records operations' policy as never charging the fare difference on any route; the rewrite charges it on short crossings. Nothing in the story shows operations changing that policy.",evidence:[{id:"jira:SYN-45",quote:"We absorb the difference; we never charge it."},{line:1,quote:"On the short crossings they pay the difference."}]},
{kind:"related",lines:[1],says:"The Q3 launch notes (outside the workstream) still list long-crossings-only waiving as an open question, not a decision.",evidence:[{id:"folder:36f7cd4a2921aad6",quote:"Do we waive the fare difference on every route, or only on the long crossings?"}]},
{kind:"related",lines:[1],says:"The rewritten acceptance criteria only cover long crossings; nothing says what the short-crossing fare or receipt should be, and the 'waived' receipt line is left unqualified.",evidence:[{line:1,quote:"On a long crossing, the rebooked fare equals the original fare"},{line:1,quote:"The receipt says 'Fare difference waived'"}]},
{kind:"companion",lines:[1],says:"The story title still promises the original fare on every move to a dearer sailing, which the rewritten description no longer says for short crossings.",evidence:[{id:"jira:SYN-45",quote:"Rebooking: keep the original fare when moving to a dearer sailing"}],changes:[1]}
];
return await challenge.record(f);

